167	     * Show the current status of the field.
168	     * @param step Which iteration step it is.
169	     * @param field The field whose status is to be displayed.
170	     */
171	    public void showStatus(Field field)
172	    {
173	        if(!isVisible()) {
174	            setVisible(true);
175	        }
176	
177	        stepLabel.setText(STEP_PREFIX + simulator.getSteps() );
178	        stats.reset();
179	        infectedPopulationCount = 0;
180	
181	        fieldView.preparePaint();
182	
183	        for(int row = 0; row < field.getDepth(); row++) {
184	            for(int col = 0; col < field.getWidth(); col++) {
185	                Object actor = field.getObjectAt(row, col);
186	                if(actor != null) {
187	                    stats.incrementCount(actor, simulator);
188	                    fieldView.drawMark(col, row, getColor(actor.getClass()));
189	                    if(actor instanceof Animal){
190	                        Animal animal = (Animal) actor;
191	                        if (!animal.getHealth()){
192	                            infectedPopulationCount ++;
193	                        }
194	                    }
195	                }
196	                else {
197	                    fieldView.drawMark(col, row, EMPTY_COLOR);
198	                }
199	            }
200	        }
201	        stats.countFinished();
202	        if(simulator.isDay()){
203	            dayLabel.setText( DAY_PREFIX+ simulator.getNoOfDays() + "      Time: " + timer.getTime(simulator.getSteps()) + "   It is Day Time. ");
204	        }else{
205	            dayLabel.setText( DAY_PREFIX+ simulator.getNoOfDays() + "      Time: " + timer.getTime(simulator.getSteps()) + "   It is Night Time ");
206	        }
207	
208	        infoLabel.setText(" " + simulator.getWeather() + "        " + INFECTION_PREFIX + infectedPopulationCount );
209	        population.setText(POPULATION_PREFIX + stats.getPopulationDetails(field, simulator));
210	        fieldView.repaint();
211	    }
